{"new_string": "// STATUS LIST MODAL — Show all items in a given state
function showStatusList(filter) {
  const allViewers = [
    {key:'linkedin-msgs', label:'LinkedIn Msg', arr:LINKEDIN_MSGS},
    {key:'emails', label:'Email', arr:EMAILS},
    {key:'x-posts', label:'X Post', arr:X_POSTS},
    {key:'blog-posts', label:'Blog', arr:BLOG_POSTS},
    {key:'linkedin-posts', label:'LinkedIn Post', arr:LINKEDIN_POSTS}
  ];
  const titles = {total:'All Items', approved:'Approved Items', sent:'Sent Items', queued:'Queued Items'};
  const title = titles[filter] || 'Items';
  let items = [];
  allViewers.forEach(v => {
    (v.arr || []).forEach(item => {
      if (isDeleted(item.id)) return;
      const sent = isSent(item.id);
      const approved = isApproved(item.id);
      let match = false;
      if (filter === 'total') match = true;
      else if (filter === 'sent') match = sent;
      else if (filter === 'approved') match = !sent && approved;
      else if (filter === 'queued') match = !sent && !approved;
      if (match) items.push({ viewer:v.label, viewerKey:v.key, item:item, status:sent?'sent':approved?'approved':'pending' });
    });
  });
  document.getElementById('slmTitle').textContent = title;
  document.getElementById('slmCount').textContent = items.length + ' item' + (items.length!==1?'s':'');
  const body = document.getElementById('slmBody');
  if (items.length === 0) {
    body.innerHTML = '<div class="slm-empty">No items in this state.</div>';
  } else {
    const viewerColors = {'LinkedIn Msg':'#0a66c2','Email':'var(--secondary)','X Post':'var(--accent)','Blog':'var(--warning)','LinkedIn Post':'var(--purple)'};
    body.innerHTML = items.map(it => {
      const label = it.item.subject || it.item.title || it.item.copy?.substring(0,50) || it.item.id;
      const statusClass = it.status === 'sent' ? 's-sent' : (it.status === 'approved' ? 's-approved' : 's-pending');
      const statusLabel = it.status === 'sent' ? '✓ Sent' : (it.status === 'approved' ? '✔ Approved' : '⏳ Pending');
      const color = viewerColors[it.viewer] || 'var(--text-muted)';
      return `<div class="slm-item" onclick="closeStatusList();document.querySelector('.tab-btn[data-tab=\\'${it.viewerKey}\\']').click();document.querySelector('.filter-input[data-viewer=\\'${it.viewerKey}\\']').value='${escapeHtml(label.substring(0,30))}';document.querySelector('.filter-input[data-viewer=\\'${it.viewerKey}\\']').dispatchEvent(new Event('input'))">
        <span class="slm-badge" style="background:${color}15;color:${color}">${it.viewer}</span>
        <span class="slm-title">${escapeHtml(label)}</span>
        <span class="slm-status ${statusClass}">${statusLabel}</span>
      </div>`;
    }).join('');
  }
  document.getElementById('slmOverlay').classList.add('active');
}
function closeStatusList() {
  document.getElementById('slmOverlay').classList.remove('active');
}
// Close on overlay click
document.addEventListener('DOMContentLoaded', function() {
  var overlay = document.getElementById('slmOverlay');
  if (overlay) overlay.addEventListener('click', function(e) { if (e.target === this) closeStatusList(); });
});

